package com.bank.insight;

import java.math.BigDecimal;
import java.util.Arrays;
import java.util.List;
import java.util.logging.ConsoleHandler;
import java.util.logging.Formatter;
import java.util.logging.LogRecord;
import java.util.logging.Logger;

public class AverageSpendDemo {
    private static final Logger log = Logger.getLogger(AverageSpendDemo.class.getName());

    static {
        Logger root = Logger.getLogger("");
        for (var h : root.getHandlers()) root.removeHandler(h);
        ConsoleHandler handler = new ConsoleHandler();
        handler.setFormatter(new BankLogFormatter());
        root.addHandler(handler);
    }

    public static void main(String[] args) {
        List<BigDecimal> monthlySpend = Arrays.asList(
            new BigDecimal("12000.00"),
            new BigDecimal("15500.00"),
            new BigDecimal("9800.00"));

        Account rajesh = new Account("SAV2001", "Rajesh Kumar", monthlySpend);
        SpendAnalyzer analyzer = new SpendAnalyzer();

        BigDecimal avg = analyzer.findAverage(rajesh.getAmounts());
        log.info(() -> "Average monthly spend for " + rajesh.getHolderName()
                + " (" + rajesh.getAccountId() + ") = Rs." + avg);
    }
}

class BankLogFormatter extends Formatter {
    @Override
    public String format(LogRecord r) {
        return String.format("%1$tF %1$tT [%2$s] %3$s%n",
                new java.util.Date(r.getMillis()), r.getLevel(), r.getMessage());
    }
}
