package com.bank.insight;

import java.math.BigDecimal;
import java.math.RoundingMode;
import java.util.List;

class SpendAnalyzer {

    // Sum in one pass, then divide with explicit scale + rounding.
    BigDecimal findAverage(List<BigDecimal> amounts) {
        if (amounts == null || amounts.isEmpty()) {
            throw new IllegalArgumentException("No amounts: average is undefined");
        }
        BigDecimal sum = BigDecimal.ZERO;
        for (BigDecimal current : amounts) {
            sum = sum.add(current);                       // accumulate total
        }
        BigDecimal count = new BigDecimal(amounts.size());
        // 2 decimal places, HALF_UP — standard for rupees display
        return sum.divide(count, 2, RoundingMode.HALF_UP);
    }
}
